      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/19~23)고콜레스테롤 관련 온라인 1:1 인터뷰 조사<환자 타입 2>\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.15. 12:50\n조회 63\n구독\n10/19~23)고콜레스테롤 관련 온라인 1:1 인터뷰 조사<환자 타입 2>\n신청하신분은 재신청 안하셔도 됩니다\n대상자 조건 :\n<공통조건>\n* 만 40세 이상, 고콜레스테롤 진단받음, 고콜레스테롤 치료를 위해 약물 복용을 권고 받은 적 있음,\n고콜레스테롤 치료를 위해 과거에 약물 복용했지만 현재는 복용하고 있지 않거나 아직 복용한 경험이 없음,\n동형접합 가족성 고콜레스테롤혈증(HoFH)으로 진단되지 않음\n* 본인이나 가족 중 제약회사/의료 기기 회사/시장조사/의료기관에 근무하는 분 없어야 함\n현재 아래 조건에 해당되는 환자 모집만 남았습니다.\n<환자 타입 2>에 해당되는 분으로 여성/만60세이상/약물복용경험없음/위험인자 없음\n* 만 60세 이상 여성, 고콜레스테롤 진단받음, 고콜레스테롤 치료를 위해 약물 복용을 권고 받은 적 있으나 아직 고지혈증 약물을 복용하지 않는 분\n* 막힌 동맥의 혈류 회복을 위해 의료 시술을 받으신 적이 없음(혈관 재개통술, 관상동맥 우회술(CABG) 또는 스텐트 시술이라고도 불림)\n* 죽상동맥경화증, 심근경색, 심장질환(CAD/CHD/허혈성심장질환), 미니뇌졸중/TIA, 뇌졸중, PAD, 급성사시허혈, 죽상동맥경화증과 관련된 발목 위 절단 중에서\n\"죽상동맥경화증\"만 진단을 받았거나 제시된 질환을 진단받지 않았어야 함\n* 아래 위험 인자가 없는 분\n(1) 이형접합가족성고콜레스테롤혈증(HeFH)\n(2) 직계가족이 55세 이전에 심근경색, 심장질환(CAD/CHD/허혈성심장질환), TIA, 뇌졸중 중에서 1개 이상 경험\n(3) 제2형 당뇨병 진단받음\n(4) 현재 흡연 또는 과거 흡연\n(5) 고혈압 약 복용\n답례비 : 5만원\n▷아래 질문에 응답해주세요 (가로로 쭉 작성해주세요)\n이름 / 전화번호 / 성별 / 나이(생년월일) / 거주지 (OO구 OO동) / 직업 / 3개월 내에 접종한 백신이름(종류) / 진단받은 질환명 / 현재 복용하고 있는 약물명\nhttps://forms.gle/V4Xc2qdtpu2ptJxYA\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.15. 14:12 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 만14~30세 한국거주 남성 ) 게임 사용자 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n10/19~23)고콜레스테롤 관련 온라인 1:1 인터뷰 조사<환자 타입 2>\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n취미생활 가정방문 조사는 모집 마감하였습니다.감사합니다!\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
