      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n게임 사용자 온라인 커뮤니티 조사\n앱 열기\n고유링크) 만14~30세 한국거주 여성 ) 게임 사용자 온라인 커뮤니티 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.15. 13:55\n조회 51\n구독\n고유링크) 만14~30세 한국거주 남녀 ) 게임 사용자 온라인 커뮤니티 조사\n장소 : 인터넷이 안정적인 장소 ( 집 등등)\n게임 사용자 온라인 커뮤니티 조사에 참여 안하신분만 신청해주세요~\n최종 선정 후 최대 6개월간 진행 가능하신분만 신청해 주세요~\n<게임 사용자 온라인 커뮤니티 조사> 총 100명 모집\n신청(참여)하신분은 재신청 안하셔도 됩니다 ~\n- 연령: 만 14~30세 한국 거주 남녀 (만 18세 미만 미성년자는 보호자의 동의 필수)\n- 조건: 1주일에 최소 1회 이상 게임(PC, 모바일, 콘솔 포함)을 즐겨하시는 분\n- 멀티 플레이어 게임에 참여하시는 분\n- 참여방법: 온라인 커뮤니티에 참여하여 한달에 2회 정도의 과제 수행, 최종 선정 후 최대 6개월간 진행\n- 사례비: 과제당 최대 $10 (과제당 소요시간 약 10분)\n- 참여를 위해 본 서베이를 작성해 주시면 대상자로 선정되신 분께 참여 링크를 발송해 드립니다.\n- 이미 동일한 커뮤니티에 참여하고 계신 분은 중복 신청할 경우 모든 계정이 무효 처리됩니다.\n<좌담회 카페 단독 고유링크>\nhttps://forms.gle/9WevZAFiz2WZak9ZA\n좌담회\n좌담회알바\n좌담회카페\n좌담회알바 좌담회카페\n중학생알바\n고등학생알바\n대학생알바\n직장인알바\n주부알바\n단기알바\nN잡알바\n투잡알바\n유튜브 게임 쇼츠 나가고 있습니다 ^^\nhttps://www.youtube.com/shorts/6033uYYCbsA\n#N잡알바\n#투잡알바\n#단기알바\n#좌담회\n#좌담회알바\n#좌담회카페\n#좌담회알바좌담회카페\n#대학생알바\n#대학원생알바\n#직장인알바\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.15. 14:11 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10/19~30)이주민 문화다양성 오프라인 좌담회: 한국에 거주하고있는 외국인근로자 / 결혼이민자 / 중국동포 / 유학생 여성\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n고유링크) 만14~30세 한국거주 여성 ) 게임 사용자 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n고유링크) 만14~30세 한국거주 남성 ) 게임 사용자 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n10/19~23)고콜레스테롤 관련 온라인 1:1 인터뷰 조사<환자 타입 2>\n좌담회알바좌담회카페\n26.10.15.\n댓글\n1\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
