      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/27~28) 만20~49세 남녀 대학생, 직장인, 자영업, 프리랜서, 전업주부) 주류 관련 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.15. 17:58\n조회 141\n구독\n10/27~28) 만20~49세 남녀 대학생, 직장인, 자영업, 프리랜서, 전업주부) 주류 관련 좌담회\n신청하신분은 재신청 안하셔도 됩니다\n대상자 조건\n만20~49세 남녀\n월1회 이상 주류(맥주) 구매,음용하시는 분\n본인의 생각을 자유롭고 적극적으로 표현해 주실 분\n낯선이들과의 대화에 거부감이 없으신 분\n대학생, 직장인, 자영업, 프리랜서, 전업주부 (취준생, 무직 제외)\n대상1_식단, 운동을 지속 가능한 수준으로 정해진 루틴은 없지만 꾸준히 하고 계시는 분\n대상2-건강관리에 관심이 많아 운동과 식단을 적극적으로 하고 계시는 분\n조사 일시\n10/27(화) 오후 3시 만 35~49세 남,여\n10/27(화) 오후 7시 만 20~34세 남,여\n10/28(수) 오후 3시 만 35~49세 남,여\n10/28(수) 오후 7시 만 20~34세 남,여\n연령별 시작 시각은 확정이나, 참석 일자는 사전 스크리닝후 결정 됩니다\n소요시간 2시간 30분 내외\n진행 장소 2호선 충정로역\n사례비 7만원\n신청시 기재 사항\n성명/연락처/생년월일/성별/직업 ( 학생-학교/학과/학년, 직장인-직장명/업종)/결혼 여부\n최근 1개월내 음용경험 있는 주류 종류\n최근 3개월내 무알콜/논알콜 맥주 음용 경험 ( 경험자, 무경험자 모두 대상)\n해당 대상 번호\nhttps://forms.gle/qUZrnH6DcWGoK2Ez7\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10~11월 중) 가사·간병 종사자 좌담회-20대 남녀\n좌담회알바좌담회카페\n26.10.15.\n댓글\n0\n10/27~28) 만20~49세 남녀 대학생, 직장인, 자영업, 프리랜서, 전업주부) 주류 관련 좌담회\n좌담회알바좌담회카페\n26.10.15.\n댓글\n0\n10/21~11/4)30대, 50대,남녀 만 가능) 자동차(주행테스트)\n좌담회알바좌담회카페\n26.10.15.\n댓글\n0\n10월~11월 진행) 남성용 요실금 관련 패드제품 유치 테스트 및 좌담회-서울/경기/인천 거주 만 40세 이상 기혼남성\n좌담회알바좌담회카페\n26.10.15.\n댓글\n0\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
